function action_form_start(string $action,string $page): void {
 echo '<form method="post" action="index.php?page='.e($page).'" class="form-stack">'.csrf_input().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="return_page" value="'.e($page).'">';
}
function selection_locations(array $locations,string $name='location_id',bool $optional=true): void {
 echo '<select name="'.e($name).'">';
 if($optional) echo '<option value="">— Aucun / choisir —</option>';
 foreach($locations as $r)echo '<option value="'.(int)$r['id'].'">'.e($r['code'].' · '.$r['label']).'</option>';
 echo '</select>';
}
function heading_card(string $title,string $desc=''): void {
 echo '<div class="section-heading"><div><h2>'.e($title).'</h2>'.($desc!==''?'<p>'.e($desc).'</p>':'').'</div></div>';
}
function badge_status(string $status): string {
 $m=['sealed'=>['Neuve','green'],'open'=>['Ouverte','blue'],'empty'=>['Vide','gray'],'archived'=>['Archivée','gray'],'planned'=>['Planifié','gray'],'in_progress'=>['En cours','blue'],'on_hold'=>['En pause','amber'],'done'=>['Terminé','green'],'operational'=>['En service','green']];
 [$text,$class]=$m[$status]??[$status,'gray'];
 return '<span class="tag tag-'.$class.'">'.e($text).'</span>';
}
