function view_components():void {
 $db=db();$locations=$db->query('SELECT id,code,label FROM storage_locations ORDER BY code')->fetchAll();
 $q=trim((string)($_GET['q']??''));
 $sql='SELECT c.*,COALESCE(SUM(s.quantity),0) AS total FROM components c LEFT JOIN component_stocks s ON s.component_id=c.id';
 if($q!=='') { $sql.=' WHERE c.name LIKE :q1 OR c.mpn LIKE :q2 OR c.manufacturer LIKE :q3'; }
 $sql.=' GROUP BY c.id ORDER BY c.id DESC LIMIT 200';
 $stmt=$db->prepare($sql);if($q!=='')$stmt->execute(['q1'=>'%'.$q.'%','q2'=>'%'.$q.'%','q3'=>'%'.$q.'%']);else $stmt->execute();
 $items=$stmt->fetchAll();$stocks=$db->query('SELECT s.component_id,s.quantity,l.code FROM component_stocks s JOIN storage_locations l ON l.id=s.location_id WHERE s.quantity>0 ORDER BY l.code')->fetchAll();
 $byComponent=[];foreach($stocks as $s)$byComponent[$s['component_id']][]=$s;
 layout_start('Électronique','Références techniques, quantités et localisation de tes composants.','components');
 ?><div class="roadmap-strip"><?=icon('link')?><span><strong>Intégrations fournisseurs :</strong> les connecteurs Mouser/DigiKey et l'import automatique des médias seront ajoutés dans une étape suivante. Tu peux déjà gérer les fiches et stocks manuellement.</span></div>
 <section class="panel"><details class="create-details"><summary><?=icon('plus')?> Ajouter un composant</summary><?php action_form_start('component_add','components'); ?><div class="form-grid"><label>Nom<input name="name" required placeholder="Résistance 10 kΩ"></label><label>Référence fabricant (MPN)<input name="mpn" placeholder="RC0603FR-0710KL"></label><label>Fabricant<input name="manufacturer" placeholder="Yageo"></label><label>Catégorie<input name="category" placeholder="Résistances / CMS"></label><label class="full">Description<textarea name="description" rows="2"></textarea></label><label class="full">URL du datasheet<input name="datasheet_url" type="url" placeholder="https://..."></label><label>Quantité initiale<input name="quantity" type="number" min="0" step="1" value="0"></label><label>Emplacement initial<?php selection_locations($locations); ?></label></div><button class="btn btn-primary">Enregistrer le composant</button></form></details></section>
 <section class="panel"><div class="section-heading"><div><h2>Catalogue de composants</h2><p>Références et stocks enregistrés dans ta base MySQL.</p></div><span class="count-pill"><?=count($items)?> résultats</span></div><form class="search-form" method="get"><input type="hidden" name="page" value="components"><input name="q" value="<?=e($q)?>" placeholder="Nom, MPN, fabricant..." type="search"><button class="btn btn-secondary" type="submit"><?=icon('search')?> Rechercher</button></form>
 <?php if(!$items): ?><?php placeholder('Aucun composant trouvé','Ajoute une référence ou modifie les critères de recherche.'); ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>COMPOSANT</th><th>CATÉGORIE</th><th>LOCALISATION</th><th>QUANTITÉ</th><th>DOCUMENTATION</th></tr></thead><tbody><?php foreach($items as $c): ?><tr><td><strong><?=e($c['name'])?></strong><small><?=e(trim(($c['manufacturer']??'').' · '.($c['mpn']??''),' ·'))?></small></td><td><?=e($c['category']??'—')?></td><td><?php $locs=$byComponent[$c['id']]??[];if($locs): ?><?=e(implode(', ',array_column($locs,'code')))?><?php else: ?><span class="muted">Non affecté</span><?php endif ?></td><td><span class="count-pill"><?=number_format((int)$c['total'],0,',',' ')?></span></td><td><?php if($c['datasheet_url']): ?><a target="_blank" rel="noopener noreferrer" class="text-link" href="<?=e($c['datasheet_url'])?>">PDF <?=icon('external',13)?></a><?php else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
 <?php if($items && $locations && can_edit()): ?><section class="panel"><details class="create-details"><summary><?=icon('plus')?> Entrée / sortie de composants</summary><?php action_form_start('component_move','components'); ?><div class="form-grid"><label>Composant<select name="component_id"><?php foreach($items as $c): ?><option value="<?=$c['id']?>"><?=e($c['name'].($c['mpn']?' · '.$c['mpn']:''))?></option><?php endforeach ?></select></label><label>Emplacement<?php selection_locations($locations,'location_id',false); ?></label><label>Type de mouvement<select name="direction"><option value="in">Entrée en stock</option><option value="out">Sortie de stock</option></select></label><label>Quantité<input type="number" min="1" step="1" value="1" name="quantity" required></label><label class="full">Motif<input name="note" placeholder="Achat, utilisation, correction..."></label></div><button class="btn btn-primary">Valider le mouvement</button></form></details></section><?php endif ?>
 <?php layout_end();
}
